05a7b3e2 Fixed hts_open_format to honour compression field.
 hts.c | 23 +++++++++++++++++++----
 1 file changed, 19 insertions(+), 4 deletions(-)
commit 05a7b3e22bd61c8c4590f6aa508b9c0ce5b41f89
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Wed Jun 5 17:33:26 2019 +0100

    Fixed hts_open_format to honour compression field.

    Previously if we asked for compressed text formats it refused to
    compression them, instead requiring us to add "z" to the mode string.
    The purpose of this function is to override the mode if we've supplied
    an htsformat struct, which is what it does elsewhere with formats.

    Made htsExactFormat actually hold the exact format when writing rather
    than morphing "bam" to "binary" and "sam" to "text" which made
    subsequent checking of opened formats rather tedious.

    Also fixed a 1 byte buffer overrun in hts_open_format when given 100
    character long mode string.  Further reduced this to accept 99 long in
    order to be compatible with the hts_hopen implementation (it'd lose
    the trailing format code before).

diff --git a/hts.c b/hts.c
index 05aaa26b..bf7a3f59 100644
--- a/hts.c
+++ b/hts.c
@@ -393,14 +393,14 @@ char *hts_format_description(const htsFormat *format)

 htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
 {
-    char smode[102], *cp, *cp2, *mode_c;
+    char smode[101], *cp, *cp2, *mode_c;
     htsFile *fp = NULL;
     hFILE *hfile = NULL;
     char fmt_code = '\0';
     const char format_to_mode[] = "\0g\0\0b\0c\0\0b\0g\0\0";

-    strncpy(smode, mode, 100);
-    smode[100]=0;
+    strncpy(smode, mode, 99);
+    smode[99]=0;
     if ((cp = strchr(smode, ',')))
         *cp = '\0';

@@ -416,7 +416,6 @@ htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
     mode_c = cp2;
     *cp2++ = fmt_code;
     *cp2++ = 0;
-    *cp2++ = 0;

     // Set or reset the format code if opts->format is used
     if (fmt && fmt->format > unknown_format
@@ -424,6 +423,13 @@ htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
         *mode_c = format_to_mode[fmt->format];
     }

+    // If we really asked for a compressed text format then mode_c above will
+    // point to nul.  We set to 'z' to enable bgzf.
+    if (strchr(mode, 'w') && fmt && fmt->compression == bgzf) {
+        if (fmt->format == sam || fmt->format == vcf || fmt->format == text_format)
+            *mode_c = 'z';
+    }
+
     char *rmme = NULL, *fnidx = strstr(fn, HTS_IDX_DELIM);
     if ( fnidx ) {
         rmme = strdup(fn);
@@ -438,6 +444,15 @@ htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
     fp = hts_hopen(hfile, fn, smode);
     if (fp == NULL) goto error;

+    // Compensate for the loss of exactness in htsExactFormat.
+    // hts_hopen returns generics such as binary or text, but we
+    // have been given something explicit here so use that instead.
+    if (fp->is_write && fmt &&
+        (fmt->format == bam || fmt->format == sam ||
+         fmt->format == vcf || fmt->format == bcf ||
+         fmt->format == bed))
+        fp->format.format = fmt->format;
+
     if (fmt && fmt->specific)
         if (hts_opt_apply(fp, fmt->specific) != 0)
             goto error;
commit 086c9c176d1b5a3267f4e3b1964af4ddfc0c8163
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Tue Aug 20 14:03:25 2019 +0100

    Auto-sense .gz extension in hts_open.

    If we're not opening a binary format (code 'b' or 'c') and we know the
    filename and it ends in .gz, then pretend mode 'z' was also added to
    the format string.

    This also permits samtools to output compressed SAM, which previously
    it had no way of enabling.

diff --git a/hts.c b/hts.c
index 8173de6e..404150ac 100644
--- a/hts.c
+++ b/hts.c
@@ -428,6 +428,9 @@ htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
     if (strchr(mode, 'w') && fmt && fmt->compression == bgzf) {
         if (fmt->format == sam || fmt->format == vcf || fmt->format == text_format)
             *mode_c = 'z';
+    } else if (!*mode_c && !strchr(smode, 'z') &&
+               strlen(fn) > 3 && strcmp(fn+strlen(fn)-3, ".gz") == 0) {
+        *mode_c = 'z';
     }

     char *rmme = NULL, *fnidx = strstr(fn, HTS_IDX_DELIM);
